def solution(input_string):
    lines = input_string.strip().split('\n')
    n, e = map(int, lines[0].split())

    hate = set()
    for i in range(e):
        a, b = map(int, lines[1 + i].split())
        hate.add((min(a, b), max(a, b)))

    trainers_wishes = []
    idx = 1 + e
    for trainer in range(1, n + 1):
        l = int(lines[idx])
        idx += 1
        wish_list = list(map(int, lines[idx].split()))
        idx += 1
        trainers_wishes.append(wish_list)

    teams_in_use = set()
    for wish_list in trainers_wishes:
        teams_in_use.update(wish_list)
    max_team = max(teams_in_use)

    team_conf = {}
    trainer_team = [None] * (n + 1)

    def calculate_hate():
        h = 0
        for (a, b) in hate:
            if trainer_team[a] is not None and trainer_team[b] is not None:
                if team_conf[trainer_team[a]] != team_conf[trainer_team[b]]:
                    h += 1
        return h

    for team in teams_in_use:
        team_conf[team] = random.randint(1, 2)

    random.shuffle(trainers_wishes)

    for _ in range(min(100, n * 2)):
        for i, wishes in enumerate(trainers_wishes):
            trainer = i + 1
            current = trainer_team[trainer]
            if current is None or random.random() < 0.3:
                for w in wishes:
                    if team_conf[w] != team_conf[random.choice(list(teams_in_use))]:
                        trainer_team[trainer] = w
                        break

    max_hate = calculate_hate()
    for i in range(max(n, 50)):
        improved = False
        for i, wishes in enumerate(trainers_wishes):
            trainer = i + 1
            current = trainer_team[trainer]
            if current is not None:
                for w in wishes:
                    if team_conf[w] != team_conf[random.choice(list(teams_in_use))]:
                        trainer_team[trainer] = w
                        break
            h = calculate_hate() if any(trainer_team[a] is None for a in [1]) else max_hate
            if h > max_hate:
                max_hate = h
                improved = True
            if max_hate >= e // 2:
                break
        if not improved and max_hate < e // 2:
            break

    result_teams = [str(trainer_team[i]) for i in range(1, n + 1)]
    conf_list = ['2' if team_conf.get(i, 2) == 1 else '1' for i in range(1, max_team + 1)]

    return ' '.join(result_teams) + '\n' + ' '.join(conf_list)

