        adj[x].append((y, i + 1))
        adj[y].append((x, i + 1))

    def is_connected(graph, s, t):
        visited = [False] * (n + 1)
        queue = deque([s])
        visited[s] = True
        while queue:
            u = queue.popleft()
            for v, e_id in graph[u]:
                # Skip edge e_id if marked as removed
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return visited[t]

    def mark_and_check(graph, removed_ids: set, s, t):
        visited = [False] * (n + 1)
        queue = deque([s])
        visited[s] = True
        while queue:
            u = queue.popleft()
            for v, e_id in graph[u]:
                if e_id not in removed_ids and not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return visited[t]

    # Store edges by their index for speed
    edge_by_id = {}
    for i, (x, y, w, idx) in enumerate(edges):
        edge_by_id[idx] = (x, y, w, i)

    # Check if s and t are already disconnected (0 roads to close)
    cost = float('inf')
    result_edges = []
    num_closed = -1

    if not is_connected(adj, s, t):
        return "0\n0\n"

    # Try closing 1 road - find minimum cost edge removal
