        num_closed = 0

    # Try closing 2 roads - find minimum cost pair of edge removals
    if num_closed == config_num_1_closed:
        min_cost = float('inf')
        best_edges = []

        # Use optimization: only check pairs where both edges are on some path from s to t
        # For efficiency, we'll use a simpler approach with early exit
        for i in range(m):
            x1, y1, w1, _ = edge_by_id[edges[i][3]]
            removed1 = {edges[i][3]}

            # Check if edge removal leaves any path
            graph = [edge_list[:] for edge_list in adj]

            for j in range(i, m):
                x2, y2, w2, _ = edge_by_id[edges[j][3]]
                removed = removed1 | {edges[j][3]}

                if not mark_and_check(adj, removed, s, t):
                    total = w1 + w2
                    if total < min_cost:
                        min_cost = total
                        best_edges = [edges[i][3] + 1, edges[j][3] + 1]

