    # pair[i] = partner of city i, 0 means not yet paired (during backtracking)
    pair = [0] * n

    # Check if current pairing is stable
    def is_stable():
        # First check all cities are paired
        for i in range(n):
            if pair[i] == 0:
                return False
            if pair[pair[i]] != i:
                return False

        # No two cities have same partner (already checked above)

        # Check stability for each pair (i, j) where i < j
        for i in range(n):
            j = pair[i]
            if i > j:
                continue

            # For pair (i, j), check if they are stable
            # Stability requires that neither i nor j would prefer to switch partners
            # But since each is paired with the other, this is always satisfied if the pairing exists

        return True

    # Check if this gives a valid pairing (everyone paired properly)
    def is_valid():
        for i in range(n):
            if pair[i] == 0 or pair[pair[i]] != i:
                return False
        return True

    def backtrack(i):
        if i == n:
            return is_valid()

        # Try to pair city i with some unpaired city j > i
        for j in range(i + 1, n):
            if pair[j] == 0:  # j is not yet paired with anyone > j
                # Pair i with j
                pair[i] = j
                pair[j] = i

                result = backtrack(i + 1)
