def grundy(x, k):
    """Calculate Grundy number for a pile of size x with parameter k"""
    if x == 0:
        return 0

    memo = {}

    def helper(val):
        if val in memo:
            return memo[val]

        # Option 1: Remove 1 cow -> get G(val-1)
        reachable = {helper(val - 1)}

        # Option 2: If val is even, replace with k piles of val/2
        if val % 2 == 0:
            if k % 2 == 0:
                reachable.add(0)  # Even number of same Grundy values XOR to 0
            else:
                gx = helper(val // 2)
                reachable.add(gx)  # Odd number of same Grundy values XOR to gx

        result = 0
        while result in reachable:
            result += 1
        memo[val] = result
        return result

    return helper(x)

