                for top in range(n - size + 1):
                    for left in range(m - size + 1):
                        r1, c1 = top, left
                        r2, c2 = top + size - 1, left + size - 1

                        # Check border
                        is_border_valid = True

                        # Top row: (r1, c1) to (r1, c2)
                        for c in range(c1, c2 + 1):
                            if matrix[top][c] == '0':
                                is_border_valid = False
                                break
                        if not is_border_valid:
