                        # Bottom row: (r2, c1) to (r2, c2)
                        for c in range(c1, c2 + 1):
                            if matrix[top + size - 1][c] == '0':
                                is_border_valid = False
                                break
                        if not is_border_valid:
                            continue

                        # Left column: (r1, c1) to (r2, c1)
                        for row in range(top, top + size):
                            if matrix[row][left] == '0':
                                is_border_valid = False
                                break
                        if not is_border_valid:
                            continue

                        # Right column: (r1, c2) to (r2, c2)
                        for row in range(top, top + size):
                            if matrix[row][left + size - 1] == '0':
                                is_border_valid = False
                                break
                        if not is_border_valid:
                            continue

                        # Check no foreign 1s touching
                        for dr in range(-1, 2):
                            for dc in range(-1, 2):
                                nr, nc = top - 1 + dr, left - 1 + dc
                                if 0 <= nr < n and 0 <= nc < m:
                                    if matrix[nr][nc] == '1':
                                        is_border_valid = False
                                        break
                            if not is_border_valid:
                                break

                        if is_border_valid:
                            # Check interior has 0s (square has at least one 1 on border anyway)
                            interior_ok = True
                            for nr in range(top + 1, top + size - 1):
                                for nc in range(left + 1, left + size - 1):
                                    if matrix[nr][nc] == '1':
                                        interior_ok = False
                                        break
                                if not interior_ok:
                                    break

                            if interior_ok:
                                count += 1

            # Type 2: Diagonal squares (diamond shape at 45 degrees)
            # For diagonal square with half-size s, the diamond spans from Manhattan distance 0 to s from center
            # Border is at Manhattan distance s from center
            for s in range(1, min(n - 1, m - 1) + 1):
                for center_r in range(s + 1, n - s):
                    for center_c in range(s + 1, m - s):
                        # Check border of diagonal square
                        border_ok = True

                        # The diamond has "shell" at Manhattan distance s from center
                        # Check all 1s are exactly at distance s, and no foreign 1s touch

                        # Check all 1s surrounding the square
                        for dr in range(-1, 2):
                            for dc in range(-1, 2):
                                nr, nc = center_r + dr, center_c + dc
                                if 0 <= nr < n and 0 <= nc < m and matrix[nr][nc] == '1':
                                    # This 1 must be part of the square or foreign
                                    manhattan_dist = abs(nr - center_r) + abs(nc - center_c)
                                    if manhattan_dist != s:
                                        border_ok = False
                                        break
                            if not border_ok:
                                break

                        if not border_ok:
                            continue

                        # Check no 1s at distance < s (interior should be empty)
                        for dr in range(1, s):
                            for dc in range(1, s):
                                nr, nc = center_r + dr, center_c + dc
                                if 0 <= nr < n and 0 <= nc < m:
                                    if matrix[nr][nc] == '1':
                                        border_ok = False
                                        break
                            if not border_ok:
                                break

                        if not border_ok:
                            continue

                        # Count how many 1s are exactly at Manhattan distance s
                        ones_at_border = 0
                        for d in range(s):
                            for deltaX in range(-d, d + 1):
                                deltaY = abs(d - abs(deltaX))
                                for dy in [deltaY, -deltaY]:
                                    nr, nc = center_r + dy, center_c + deltaX
                                    if 0 <= nr < n and 0 <= nc < m:
                                        if matrix[nr][nc] == '1':
                                            ones_at_border += 1

                        if ones_at_border == 0:
                            continue

                        # Check no foreign 1s touching by side or corner
                        for check_dr in range(-1, 2):
                            for check_dc in range(-1, 2):
                                c_nr, c_nc = center_r + check_dr, center_c + check_dc
                                if 0 <= c_nr < n and 0 <= c_nc < m:
                                    c_dist = abs(c_nr - center_r) + abs(c_nc - center_c)
                                    if matrix[c_nr][c_nc] == '1' and c_dist != s:
                                        border_ok = False
                                        break
                            if not border_ok:
                                break

                        if border_ok and ones_at_border > 0:
                            count += 1

        results.append(str(count))

    return '\n'.join(results)

