    x1, y1, x2, y2 = map(int, lines[1].split())

    # Initialize overall time bounds
    overall_min = 0.0  # Minimum valid time (non-negative)
    overall_max = float('inf')  # Maximum valid time across all mice AND

    def get_x_bounds(rix, vix):
        """Return (start, end) of time interval when mouse is strictly inside x1 < x < x2"""
        if vix == 0:
            if not (x1 < rix < x2):
                return None  # Never inside in x
            return (float('-inf'), float('inf'))  # Always inside
        else:
            t1 = (x1 - rix) / vix
            t2 = (x2 - rix) / vix
            return (min(t1, t2), max(t1, t2))

    def get_y_bounds(riy, viy):
        """Return (start, end) of time interval when mouse is strictly inside y1 < y < y2"""
        if viy == 0:
            if not (y1 < riy < y2):
                return None  # Never inside in y
            return (float('-inf'), float('inf'))  # Always inside
        else:
            t1 = (y1 - riy) / viy
            t2 = (y2 - riy) / viy
            return (min(t1, t2), max(t1, t2))

    for i in range(2, 2 + n):
        rix, riy, vix, viy = map(int, lines[i].split())

        # Get x time interval for this mouse
        x_bounds = get_x_bounds(rix, vix)
        y_bounds = get_y_bounds(riy, viy)

        if x_bounds is None or y_bounds is None:
            return "-1"

        # Mouse is inside at time t when:
        # x_bounds[0] < t < x_bounds[1] AND y_bounds[0] < t < y_bounds[1]
        # Combined: max(x_bounds[0], y_bounds[0]) < t < min(x_bounds[1], y_bounds[1])

        mouse_min = max(x_bounds[0], y_bounds[0])
        mouse_max = min(x_bounds[1], y_bounds[1])

        # Intersection with valid time range [0, inf)
        overall_min = max(overall_min, mouse_min)
        overall_max = min(overall_max, mouse_max)

        # If already invalid (start >= end or no room for non-negative time)
        if overall_min >= overall_max:
            return "-1"

    # Final answer: smallest t >= 0 that works for all
    if overall_max <= overall_min:
        return "-1"

    if overall_min < 0:
        overall_min = 0.0

    # Check if we have a non-negative time window
    if overall_min >= overall_max:
        return "-1"

    return str(overall_min)

