            if n <= a:
                break
            x = pow(a, d, n)
            if x == 1 or x == n - 1:
                continue
            for _ in range(r - 1):
                x = pow(x, 2, n)
                if x == n - 1:
                    break
            else:
                return False
        return True

    def is_lucky_for_both(n):
        # Peter: prime
        # Bob: n = 2 or n ≡ 1 (mod 4) - can be written as sum of two positive squares
        if n == 2:
            return is_prime_miller_rabin(n)
        if n % 4 == 1:
            return is_prime_miller_rabin(n)
        return False

