            return True

        # General case with non-zero first element
        ratio = seq[1] / seq[0] if seq[0] != 0 else 0
        for i in range(2, len(seq)):
            expected = seq[0] * ratio ** i
            if abs(expected - seq[i]) > 1e-9:
                return False
        return True

