            "-{} 0\n".format(r)
            f"{r} 0"
        ]
        return result

    # Generate all integer points within distance r from origin
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x * x + y * y <= r * r:
                if x == 0 and y == 0:
                    continue
                points.append((x, y))

    # Group points by their squared distance from origin to optimize greedy selection
    # Points with same distance are substitutes

    def squared_dist(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    def sum_squared_distances(positions):
        total = 0
        for i in range(len(positions)):
            for j in range(i + 1, len(positions)):
                total += squared_dist(positions[i], positions[j])
        return total

    best_score = -1
    best_positions = []

    # Since n is small (2-8), we can try various strategies

    # Strategy 1: All points at one location with max radius
    extreme_points = [(x, y) for x, y in points if x * x + y * y == r * r]
    if extreme_points:
        for i, p in enumerate(extreme_points):
            score = 0
            for j in range(i + 1, n):
                score += 0  # same point
            # all same point: sum of squared distances is 0
            # Actually for all same point all pairwise distances are 0
            positions = n * [p]
            score = sum_squared_distances(positions)
            if score > best_score:
                best_score = score
                best_positions = positions

    # Strategy 2: Split into 2 groups at opposite points
    if len(extreme_points) >= 2:
        for i in range(len(extreme_points)):
            for j in range(i + 1, len(extreme_points)):
                a, b = extreme_points[i], extreme_points[j]
                if a != b:
                    d2 = squared_dist(a, b)
                    k1 = n // 2
                    k2 = n - k1
                    positions = k1 * [a] + k2 * [b]
                    score = sum_squared_distances(positions)
                    if score > best_score:
                        best_score = score
                        best_positions = positions

    # Strategy 3: Try all 2-group splits for all distinct extreme points pairs
    if n <= 8 and r <= 30:
        extreme_set = extreme_points

        # Sort points by some criteria and try a reasonable number of pairs
        extreme_set = sorted(extreme_set, key=lambda p: p[0] * 100 + p[1])

        for i in range(min(20, len(extreme_set))):
            for j in range(i + 1, min(20, len(extreme_set))):
                a, b = extreme_set[i], extreme_set[j]
                if a == b:
                    continue
                k1 = n // 2
                k2 = n - k1
                positions = k1 * [a] + k2 * [b]
                score = sum_squared_distances(positions)
                if score > best_score:
                    best_score = score
                    best_positions = positions

        # Try reversed split
        for i in range(min(20, len(extreme_set))):
            for j in range(i + 1, min(20, len(extreme_set))):
                a, b = extreme_set[i], extreme_set[j]
                if a == b:
                    continue
                k1 = n // 2 + 1
                k2 = n - k1
                positions = k1 * [a] + k2 * [b]
                score = sum_squared_distances(positions)
                if score > best_score:
                    best_score = score
                    best_positions = positions

    # Strategy 4: Try configurations with 3 different locations
    if n <= 8:
        # Try rotating a set of ~5 points and assigning to different cluster centers
        candidates = extreme_set[:min(15, len(extreme_set))]

        for i in range(len(candidates)):
            for j in range(i + 1, len(candidates)):
                for k in range(j + 1, len(candidates)):
                    a, b, c = candidates[i], candidates[j], candidates[candidates.index((candidates[i], candidates[j], candidates[k])[0]) if len(candidates)>2 else 2 if len(candidates)>=2 else -1]
                    if i < j < k:
                        if k + 1 >= len(candidates):
                            continue
                        p1, p2, p3 = candidates[i], candidates[j], candidates[k]
                        if p1 == p2 or p2 == p3 or p3 == p1:
                            continue
                        # Try various distributions
                        for s1 in range(n - 2):
                            for s2 in range(n - s1 - 1):
                                s3 = n - s1 - s2
                                if s1 > 0 and s2 > 0 and s3 > 0:
                                    positions = s1 * [p1] + s2 * [p2] + s3 * [p3]
                                    score = sum_squared_distances(positions)
                                    if score > best_score:
                                        best_score = score
                                        best_positions = positions

    # Output
    output = [f"{best_score}"]
    for p in best_positions:
        output.append(f"{p[0]} {p[1]}")

    return '\n'.join(output) + '\n'

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return 'NO'

    parts = lines[0].split()
    N, M = int(parts[0]), int(parts[1])

    if M == 0:
        return 'YES\n' + ' '.join(['0.0'] * N)

    adj = [[] for _ in range(N + 1)]
    for i in range(1, M + 1):
        parts = lines[i].split()
        a, b, c = int(parts[0]), int(parts[1]), int(parts[2])
        adj[a].append((b, c))
        adj[b].append((a, c))

    visited = [False] * (N + 1)
    total_l1 = 0.0
    result = [0.0] * (N + 1)

    for start in range(1, N + 1):
        if visited[start]:
            continue

        component_nodes = []
        queue = [start]
        visited[start] = True
        expr = {start: (1.0, 0.0)}  # x[node] = coef * x[root] + const
        tree_edges = set()  # edges processed as tree edges

        while queue:
            u = queue.pop(0)
            component_nodes.append(u)

            for v, c in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
                    coef_u, const_u = expr[u]
                    # x[v] = c - x[u]
                    coef_v = -coef_u
                    const_v = c - const_u
                    expr[v] = (coef_v, const_v)
                    tree_edges.add(tuple(sorted((u, v))))

        # Check all edges including non-tree edges for consistency
        for u in component_nodes:
            for v, c in adj[u]:
                edge = tuple(sorted((u, v)))
                if edge in tree_edges:
                    continue

                # Non-tree edge - check consistency
                coef_u, const_u = expr[u]
                coef_v, const_v = expr[v]
                sum_coef = coef_u + coef_v
                sum_const = const_u + const_v

                if sum_coef != 0:
                    # This edge constrains x[root]
                    constraint = (c - sum_const) / sum_coef
                if sum_coef == 0:
                    if abs(sum_const - c) > 1e-9:
                        return 'NO'
                # else: constraint on root is sum_coef * x[root] = c - sum_const
                # Store constraint for optimization

        # Build constraints for x[root]
        root_constraints = []
        for u in component_nodes:
            for v, c in adj[u]:
                edge = tuple(sorted((u, v)))
                if edge in tree_edges:
                    continue

                coef_u, const_u = expr[u]
                coef_v, const_v = expr[v]
                sum_coef = coef_u + coef_v
                sum_const = const_u + const_v

                if sum_coef != 0:
                    root_constraints.append((c - sum_const) / sum_coef)

        if root_constraints:
            # All constraints must be consistent (equal to within tolerance)
            if len(set([round(r, 8) for r in root_constraints])) > 1:
                return 'NO'
            root_val = root_constraints[0]
        else:
            root_val = 0.0

        # Compute values and accumulate L1
        for u in component_nodes:
            coef, const = expr[u]
            result[u] = coef * root_val + const
            total_l1 += abs(result[u])

    # Check final total
    if total_l1 > 1e15:
        return 'NO'

    return 'YES\n' + ' '.join([f'{result[i]:.2f}' for i in range(1, N + 1)])

def get_block_len(b):
    """Returns the length of block b (sequence from 1 to b)"""
    if b <= 9:
        return b
    elif b <= 99:
        return 9 + 2 * (b - 9)
    elif b <= 999:
        return 9 + 180 + 3 * (b - 99)
    elif b <= 9999:
        return 9 + 180 + 2700 + 4 * (b - 999)
    else:
        return 9 + 180 + 2700 + 36000 + 5 * (b - 9999)

def find_block_and_offset(k):
    """Find which block contains position k and the offset within block"""
    LIMIT = 100000
    cum = [0] * (LIMIT + 1)
    for b in range(1, LIMIT + 1):
        cum[b] = cum[b - 1] + get_block_len(b)

    if k <= cum[LIMIT]:
        for b in range(1, LIMIT + 1):
            if cum[b] >= k:
                return b, k - cum[b - 1]
    else:
        # Binary search for block beyond LIMIT
        l, r = LIMIT, 2000000000
        ans = LIMIT
        while l <= r:
            mid = (l + r) // 2
            length = cum[LIMIT]

            # Estimate block length for larger b (most numbers have many digits)
            block = get_block_len(mid)
            if block > 0:
                total = length + block
            else:
                total = length

            if total >= k:
                ans = mid
                r = mid - 1
            else:
                l = mid + 1

        return ans, k - cum[LIMIT]

def find_number_and_digit(offset):
    """Find the number and digit at given offset in sequence 1,2,3,..."""
    pos = offset

    # Single-digit numbers (1-9)
    if pos <= 9:
        return pos, 0

    pos -= 9

    # Multi-digit numbers
    digit_len = 2
    start_num = 10
    while True:
        if digit_len == 2:
            count = 90
        elif digit_len == 3:
            count = 900
        elif digit_len == 4:
            count = 9000
        elif digit_len == 5:
            count = 90000
        else:
            count = 9 * (10 ** (digit_len - 1))

        total_len = count * digit_len

        if pos <= total_len:
            num_idx = (pos - 1) // digit_len
            digit_idx = (pos - 1) % digit_len
            return start_num + num_idx, digit_idx
        else:
            pos -= total_len
            start_num *= 10
            digit_len += 1

def get_digit_at_k(k):
    """Find the digit at position k in the infinite sequence"""
    block, offset = find_block_and_offset(k)
    num, digit_idx = find_number_and_digit(offset)
    return str(num)[digit_idx]

