        """Compute next virus state after seeing character"""
        j = curr_state
        while j > 0 and (virus[j] != char):
            j = state_arr[j-1]
        if j < k and virus[j] == char:
            j += 1
        return j

    # dp[i][j][st] = longest common subsequence found at positions (i,j) with virus state st
    dp = {}
    dp[(0, 0, 0)] = ""

    for i in range(n + 1):
        for j in range(m + 1):
            for st in range(k + 1):
                if (i, j, st) not in dp:
                    continue

