                    if new_str == dp.get(next_key, "") or dp.get(next_key, "") == "":
                        dp[next_key] = new_str

    result = max((dp[key] for key in dp), key=len) if dp else ""

    # Per problem, return "0" if no valid subsequence, else return the string
    return result if result else "0"


