        adj[u].append(v)

    # Precompute all pairs shortest paths using BFS from each city
    all_dists = [bfs(i, n, adj) for i in range(1, n + 1)]

    best_total = -1
    best_path = None

    # Try all possible middle pairs (c2, c3)
    # For each pair, find best c1 (max dist to c2) and c4 (max dist from c3)
    # ensuring all 4 cities are distinct
    for c2 in range(1, n + 1):
        for c3 in range(1, n + 1):
            if c2 == c3:
                continue

            # Find best c1 that maximizes dist(c1, c2) with c1 != c2, c3
            best_c1 = -1
            best_dist_to_c2 = -1
            for c1 in range(1, n + 1):
                if c1 == c2 or c1 == c3:
                    continue
                if all_dists[c1 - 1][c2] == -1:
                    continue
                if all_dists[c1 - 1][c2] > best_dist_to_c2:
                    best_dist_to_c2 = all_dists[c1 - 1][c2]
                    best_c1 = c1

            if best_c1 == -1:
                continue

            # Find best c4 that maximizes dist(c3, c4) with c4 != c1, c2, c3
            best_c4 = -1
            best_dist_from_c3 = -1
            for c4 in range(1, n + 1):
                if c4 == c1 or c4 == c2 or c4 == c3:
                    continue
                if all_dists[c3 - 1][c4] == -1:
                    continue
                if all_dists[c3 - 1][c4] > best_dist_from_c3:
                    best_dist_from_c3 = all_dists[c3 - 1][c4]
                    best_c4 = c4

            if best_c4 == -1:
                continue

            total = best_dist_to_c2 + all_dists[c2 - 1][c3] + best_dist_from_c3
            if total > best_total:
                best_total = total
                best_path = [best_c1, c2, c3, best_c4]

    if best_path is None:
        return "1 2 3 4"

    return " ".join(map(str, best_path))

