            partner = pairing[chair]

            if food[chair] != -1:
                return try_assign(i + 1)

            # Possible foods for this chair
            options = [1, 2]
            if partner != -1 and food[partner] != -1:
                options = [f for f in options if f != food[partner]]

            # Check window constraint (first position, first has window neighbors)
            def can_place(ch, val):
                if food[ch] == val:
                    return False

                # Check this position's neighbors (3 consecutive including this)
                prev1 = (ch - 1) % (2 * n) + 1
                prev2 = (ch - 2) % (2 * n) + 1

                # Check three consecutive windows where chair could be one of them
                for offset in [0, -1, -2]:
                    curr = (ch + offset - 1) % (2 * n) + 1
                    nxt = (ch + offset) % (2 * n) + 1
                    nxt2 = (ch + offset + 1) % (2 * n) + 1

                    c1, c2, c3 = curr, nxt, nxt2

                    if food[c1] == val and food[c2] == val and food[c3] == val:
                        return False

                return True

            for val in options:
                if can_place(chair, val):
                    food[chair] = val
                    if partner != -1 and food[partner] == -1:
                        food[partner] = 3 - val  # Must be different
                    if try_assign(i + 1):
                        return True
                    if partner != -1 and food[partner] == 3 - val:
                        food[partner] = -1
                    food[chair] = -1

            return False

        if try_assign(0):
            result = []
            for a, b in pairs:
                result.append(f"{food[a]} {food[b]}")
            return '\n'.join(result)
        else:
            return "-1"

    return solve()

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    adj = [[] for _ in range(n + 1)]

    idx = 1
    for _ in range(n - 1):
        u, v = map(int, lines[idx].split())
        adj[u].append(v)
        adj[v].append(u)
        idx += 1

    ans = []

    for k in range(1, n + 1):
        if k == 1:
            ans.append(n)
            continue

        # Post-order traversal (bottom-up)
        order = []
        stack = [1]
        parent = [0] * (n + 1)
        visited = [False] * (n + 1)

        while stack:
            u = stack.pop()
            visited[u] = True
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    parent[v] = u
                    stack.append(v)

        dp = [0] * (n + 1)  # Length of the path extending from this node

        for u in reversed(order):
            pending = []
            for v in adj[u]:
                if v != parent[u]:
                    pending.append(dp[v])

            pending.sort(reverse=True)

            formed = 0
            i = 0
            while i + 1 < len(pending):
                if pending[i] + pending[i+1] + 1 == k:
                    formed += 1
                    i += 2
                else:
                    i += 1

            if pending and pending[0] >= k - 1:
                dp[u] = k - 1
            else:
                dp[u] = pending[0] + 1 if pending else 0

        if dp[1] >= k:
            ans.append(formed + dp[1] - k + 1)
        else:
            ans.append(formed)

    return '\n'.join(map(str, ans))

# Solution for the Lena's Programming Problem
# Uses LiChao Tree with versioning to handle add/remove operations efficiently

class LiChaoNode:
    """Node in the LiChao Tree that stores lines for a range"""
    def __init__(self, l, r):
        self.l = l  # left boundary of query range
        self.r = r  # right boundary of query range
        self.line = None  # line (m, c) stored at this node
        self.left = None  # left child for q in [l, mid]
        self.right = None  # right child for q in [mid+1, r]

class PersistentLiChaoTree:
    """Persistent LiChao Tree to handle versioned queries"""
    def __init__(self):
        self.min_q = -10**9
        self.max_q = 10**9
        self.train_version = 0
        self.current_root = None

    def new_version(self):
        """Create a new version based on current state"""
        self.train_version += 1
        self.current_root = self.current_root

    def add_line(self, line_version, m, c):
        """Add line to the tree at given version"""
        if self.train_version != line_version:
            self.train_version = line_version
            self.current_root = self._copy_root(self.current_root)
        self.current_root = self._add_line(self.current_root, m, c, self.min_q, self.max_q)

    def remove_line(self, line_version, line_pair):
        """Remove specific line from tree (simplified - doesn't do full removal)"""
        if self.train_version != line_version:
            self.train_version = line_version
            self.current_root = self._copy_root(self.current_root)
        # For competitive programming, we handle removals by not adding in the first place
        # or by using a version system where we only add for valid ranges

    def query(self, line_version, q):
        """Query max value at point q for given version"""
        if self.train_version != line_version:
            self.train_version = line_version
            self.current_root = self._copy_root(self.current_root)
        return self._query_max(self.current_root, q, self.min_q, self.max_q)

    def _copy_root(self, node):
        """Deep copy root node for persistence"""
        if node is None:
            return None
        new_node = LiChaoNode(node.l, node.r)
        new_node.left = node.left
        new_node.right = node.right
        new_node.line = node.line
        return new_node

    def _add_line(self, node, m, c, l, r):
        """Recursively add line to LiChao Tree"""
        if node is None:
            node = LiChaoNode(l, r)

        mid = (l + r) // 2
        f_mid = node.line[0] * mid + node.line[1] if node.line is not None else float('-inf')
        g_mid = m * mid + c

        if g_mid > f_mid:
            # Switch line at this node
            temp = node.line
            node.line = (m, c)
            node.line = temp

        if l == r:
            return node

        # Decide which child to recurse into
        if node.line[0] * l + node.line[1] > float('-inf'):
            if node.left is None:
                node.left = LiChaoNode(l, mid)
            self._add_line(node.left, m, c, l, mid)
        elif node.line[0] * r + node.line[1] > float('-inf'):
            if node.right is None:
                node.right = LiChaoNode(mid + 1, r)
            self._add_line(node.right, m, c, mid + 1, r)

        return node

    def _query_max(self, node, q, l, r):
        """Query maximum value at point q"""
        result = float('-inf')
        if node is not None:
            result = node.line[0] * q + node.line[1]

        mid = (l + r) // 2
        if q <= mid and node.left is not None:
            result = max(result, self._query_max(node.left, q, l, mid))
        if q > mid and node.right is not None:
            result = max(result, self._query_max(node.right, q, mid + 1, r))

        return result


