class SimpleLiChao:
    """Simplified LiChao Tree for this problem"""
    def __init__(self):
        self.lines = []

    def add(self, m, c):
        """Add line y = m*x + c"""
        self.lines.append((m, c))

    def query(self, x):
        """Find max line value at x"""
        if not self.lines:
            return float('-inf')
        result = self.lines[0][0] * x + self.lines[0][1]
        for m, c in self.lines[1:]:
            val = m * x + c
            if val > result:
                result = val
        return result

    def remove(self, idx):
        """Remove line by index"""
        if idx < len(self.lines):
            del self.lines[idx]


