    # Parse edges
    edges = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        # Normalize so a < b
        if a > b:
            a, b = b, a
        edges.append((a, b))

    def is_crossing(e1, e2):
        a1, b1 = e1
        a2, b2 = e2

        # If edges share a vertex, they can't cross (roads can intersect at endpoints)
        if a1 == a2 or a1 == b2 or b1 == a2 or b1 == b2:
            return False

        # Check if exactly one endpoint of e2 is in interval (a1, b1)
        # This determines if the edges cross when arranged on a ring
        c1 = a1 < a2 < b1
        c2 = a1 < b2 < b1
        return c1 ^ c2  # XOR: true if exactly one is in interval

    # Build conflict graph
    conflict_graph = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if is_crossing(edges[i], edges[j]):
                conflict_graph[i].append(j)
                conflict_graph[j].append(i)

    # Check if bipartite using BFS coloring
    color = [-1] * m
    possible = True

    for start in range(m):
        if color[start] == -1:
            queue = [start]
            color[start] = 0
            idx = 0
            while idx < len(queue):
                u = queue[idx]
                idx += 1
                for v in conflict_graph[u]:
                    if color[v] == -1:
                        color[v] = color[u] ^ 1
                        queue.append(v)
                    elif color[v] == color[u]:
                        possible = False
                        break
                if not possible:
                    break
            if not possible:
                break

    if not possible:
        return "Impossible"

    # Output: 'i' for color 0, 'o' for color 1
    result = []
    for c in color:
        result.append('i' if c == 0 else 'o')

    return ''.join(result)


