    # Parse input
    first_line = input_str.strip().split('\n')[0]
    n, h, m = map(int, first_line.split())

    # Parse restrictions
    restrictions = []
    lines = input_str.strip().split('\n')
    for i in range(1, 1 + m):
        l, r, x, c = map(int, lines[i].split())
        restrictions.append((l, r, x, c))

    # Group restrictions by their right endpoint
    restrictions_by_r = {}
    for l, r, x, c in restrictions:
        if r not in restrictions_by_r:
            restrictions_by_r[r] = []
        restrictions_by_r[r].append((l, x, c))

    # dp[max_h] = maximum profit after processing current position
    # where max_h is the maximum height among all positions processed so far
    # Initialize: profit 0 with max height 0
    dp = [0] + [-10**18] * h

    for pos in range(1, n + 1):
        new_dp = [-10**18] * (h + 1)

        # Try all possible heights for current position
        for curr_h in range(h + 1):
            # For each possible previous max height
            for prev_max in range(h + 1):
                if prev_max > curr_h:
                    continue  # max can't decrease

                if dp[prev_max] < -10**15:
                    continue  # invalid state

                # Calculate profit: squared height + previous profit
                candidate = dp[prev_max] + curr_h * curr_h

                # When we reach position 'pos', check restrictions ending here
                if pos in restrictions_by_r:
                    for l, x, c in restrictions_by_r[pos]:
                        # Check if this restriction was not satisfied
                        # The restriction [l, pos] is violated if max height in range > x
                        # We track this by checking if prev_max (from l-1 to pos-1) > x
                        # AND if curr_h (at pos) > x, then violated
                        if max(prev_max, curr_h) > x and l <= pos:
                            candidate -= c  # Pay fine

                new_dp[curr_h] = max(new_dp[curr_h], candidate)

        dp = new_dp

    return str(max(dp))

