    limit = 3 * math.floor(math.log2(n + m))

    if not check_row_direction(r, c, n, m):
        return False
    if not check_col_direction(r, c, n, m):
        return False

    max_rows = n // r
    max_cols = m // c

    k = 1
    while k < min(max_rows, max_cols) and count < limit - 2:
        count += 1
        if query(r, c, 1 + k * r, 1 + k * c, 1, 1) != 1:
            return False
        k *= 2

    return True

