def solution(s):
    lines = s.strip().split('\n')
    n, k = map(int, lines[0].split())
    sequence = list(lines[1].rstrip())

    if n == 0:
        return "NO\n"

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i, balance):
        """
        Returns True if we can reach a valid final state starting from position i with current balance.
        A state is valid if:
        1. At position n, abs(balance) == k
        2. At any position before n, abs(balance) < k (can't reach k before end)
        """
        if abs(balance) == k:
            # If we already reached k, this is invalid unless we're at the end
            return False

        if i == n:
            # We reached the end, check if we achieved exactly k
            return abs(balance) == k

        c = sequence[i]

        for move in ['W', 'L', 'D']:
            if move not in ['?', c]:
                continue

            new_balance = balance
            if move == 'W':
                new_balance += 1
            elif move == 'L':
                new_balance -= 1

            # Prune if new_balance already reaches k (invalid - would stop before end)
            if abs(new_balance) == k:
                continue

            if dp(i + 1, new_balance):
                return True

        return False

    # Check if there's a valid sequence from start with balance 0
    if not dp(0, 0):
        return "NO\n"

    # Reconstruct the sequence by finding one valid path
    result = [''] * n
    balance = 0

    for i in range(n):
        c = sequence[i]

        for move in ['W', 'L', 'D']:
            if move not in ['?', c]:
                continue

            new_balance = balance
            if move == 'W':
                new_balance += 1
            elif move == 'L':
                new_balance -= 1

            # Skip if this move reaches k before end
            if abs(new_balance) == k:
                continue

            # Check if this move leads to a valid solution
            if dp(i + 1, new_balance):
                result[i] = move
                balance = new_balance
                break

    return ''.join(result) + '\n'

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx != ry:
            self.parent[rx] = ry

def solution(s):
    lines = s.strip().split('\n')
    t = int(lines[0])
    result = []

    for i in range(t):
        n = int(lines[1 + 3*i])
        a = lines[2 + 3*i]
        b = lines[3 + 3*i]

        # Union-find to track connected components among characters
        uf = UnionFind(26)
        involved = set()
        edge_count = 0

        for j in range(n):
            if a[j] != b[j]:
                u = ord(a[j]) - ord('a')
                v = ord(b[j]) - ord('a')
                involved.add(u)
                involved.add(v)
                uf.union(u, v)
                edge_count += 1

        if edge_count == 0:
            result.append('0')
            continue

        # Count number of connected components among involved characters
        components = 0
        for char in involved:
            if uf.parent[char] == char:
                components += 1

        # Formula: moves = edges - components + 1
        moves = edge_count - components + 1
        result.append(str(moves))

    return '\n'.join(result)

import sys

def solution(s):
    MOD = 10**9 + 7

    if not s.strip():
        return ""

    lines = s.strip().split('\n')
    if not lines:
        return ""

    q = int(lines[0])

    # n <= 10^6, so max exponent for prime factor 2 is floor(log2(10^6)) = 19
    MAX_EXP = 25
    # r <= 10^6
    MAX_R = 1000000

    # Maximum value for e + r where e <= 19 and r <= 10^6
    MAX_VAL = MAX_R + MAX_EXP + 50

    # Precompute SPF (Smallest Prime Factor) for numbers up to 10^6
    MAX_N = 1000000
    spf = list(range(MAX_N + 1))
    for i in range(2, int(MAX_N**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX_N + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Precompute factorials and inverse factorials
    fact = [1] * MAX_VAL
    finv = [1] * MAX_VAL

    for i in range(1, MAX_VAL):
        fact[i] = (fact[i-1] * i) % MOD

    finv[MAX_VAL-1] = pow(fact[MAX_VAL-1], MOD-2, MOD)
    for i in range(MAX_VAL-2, -1, -1):
        finv[i] = (finv[i+1] * (i+1)) % MOD

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * finv[k] % MOD * finv[n-k] % MOD

    def g(r, e):
        """Computes f_r(p^e) for a prime p with exponent e"""
        if e == 0:
            return 1
        # Formula: g_r(e) = C(e+r, r) + C(e+r-1, r)
        return (C(e + r, r) + C(e + r - 1, r)) % MOD

    results = []
    for i in range(1, q + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) < 2:
            continue
        r, n = int(parts[0]), int(parts[1])

        temp_n = n
        res = 1
        while temp_n > 1:
            p = spf[temp_n]
            count = 0
            while temp_n % p == 0:
                temp_n //= p
                count += 1
            res = (res * g(r, count)) % MOD
        results.append(str(res))

    return '\n'.join(results)


