                if visitors[j] < current_time:
                    pass
                else:
                    start = max(visitors[j], current_time)
                    current_time = start + t

            # Find when queue empties
            while i < n and visitors[i] < current_time + t:
                current_time = max(visitors[i], current_time) + t
                i += 1

            service_ends = current_time

            if service_ends >= ts and service_ends <= tf - t:
                # Queue has finish time, check if next visitor could shift us
                if i == n or visitors[i] > service_ends:
                    # Queue is empty from service_ends to visitors[i]-1
                    # Vasya arrives when queue empties
                    result = max(0, service_ends)
                    if result + t <= tf:
