    reachable = {0}

    from collections import deque
    queue = deque([(0, 0)])  # (sum, prev_sum_for_transition_tracking)

    while queue:
        current_sum, _ = queue.popleft()
        day += 1

        reachable = set()

        for next_sum in sorted_sums:
            if next_sum <= current_sum:
                continue
            if next_sum - current_sum <= d:  # Valid transition
                if dp[next_sum] > day:
                    dp[next_sum] = day
                    reachable.add(next_sum)

        if not reachable:
            break

    # More efficient: process day by day using reachable set
    # Reset DP for cleaner approach
    dp2 = {v: float('inf') for v in sorted_sums}
    dp2[0] = 0
    reachable_set = {0}

    for day in range(1, 100000):  # Sufficiently large upper bound
        new_reachable = set()
        for target in sorted_sums:
            if dp2[target] <= day - 1:
                continue
            # Check if target can be reached from any previous reachable sum
            for prev in reachable_set:
                if prev <= target and (target - prev) <= d:
                    dp2[target] = day - 1
                    new_reachable.add(target)
                    break

        if not new_reachable:
            break
        reachable_set.update(new_reachable)

    # Find maximum value and minimum days
    max_value = 0
    min_days = float('inf')

    for v in sorted_sums:
        if dp2[v] < float('inf'):
            if dp2[v] > min_days:
                min_days = dp2[v]
            if v > max_value or (v == max_value and dp2[v] < min_days):
                max_value = v
                min_days = dp2[v]

    # Better approach: find max value directly
    for v in sorted_sums:
        if dp2[v] != float('inf'):
            max_value = v
            min_days = dp2[v]
            break

    return f"{max_value} {min_days}"

